-- Unifica todos los clubes en public.teams para que admin y el juego usen la misma fuente de verdad.
ALTER TABLE public.teams ADD COLUMN IF NOT EXISTS division text NOT NULL DEFAULT 'primera_nacional';
UPDATE public.teams SET division = 'primera_nacional' WHERE division IS NULL OR division = '';
GRANT SELECT ON public.teams TO anon, authenticated;
GRANT INSERT, UPDATE, DELETE ON public.teams TO authenticated;
DROP POLICY IF EXISTS "teams readable" ON public.teams;
CREATE POLICY "teams readable" ON public.teams FOR SELECT TO anon, authenticated USING (true);
DROP POLICY IF EXISTS "admins insert teams" ON public.teams;
CREATE POLICY "admins insert teams" ON public.teams FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS "admins update teams" ON public.teams;
CREATE POLICY "admins update teams" ON public.teams FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
DROP POLICY IF EXISTS "admins delete teams" ON public.teams;
CREATE POLICY "admins delete teams" ON public.teams FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
DO $$ BEGIN ALTER PUBLICATION supabase_realtime ADD TABLE public.teams; EXCEPTION WHEN duplicate_object THEN NULL; END $$;

ON CONFLICT (id) DO UPDATE SET division = EXCLUDED.division;
